contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount, uint extra) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount > 0);
        require(address(this).balance >= amount);

        c.addToBalance{value: amount}(); if (__ESBMC_reverted()) return;

        uint recordedBefore = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint testBalBefore = address(this).balance;

        bool reverted;
        c.withdrawBalance(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint recordedAfter = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint testBalAfter = address(this).balance;

        assert(!reverted && recordedBefore == amount && testBalAfter >= testBalBefore + recordedBefore && recordedAfter == 0);
    }

    receive() external payable {}
}

