pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 amount, uint256 extra) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount > 0);
        vm.assume(address(this).balance >= amount);
        try c.addToBalance{value: amount}() {} catch { return; }
        uint256 recordedBefore;
        try c.getBalance(address(this)) returns (uint256 __r) { recordedBefore = __r; } catch { return; }
        uint testBalBefore = address(this).balance;
        bool reverted;
        try c.withdrawBalance() { reverted = false; } catch { reverted = true; }
        uint256 recordedAfter;
        try c.getBalance(address(this)) returns (uint256 __r) { recordedAfter = __r; } catch { return; }
        uint testBalAfter = address(this).balance;
        assertTrue(!reverted && recordedBefore == amount && testBalAfter >= testBalBefore + recordedBefore && recordedAfter == 0);
    }

    function testFuzz_run(uint256 amount, uint256 extra) public {
        _run(amount, extra);
    }

    receive() external payable {}
}
